import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {settings,indexChats} from './chat-rat-20261016.mjs';
import {terms,ask,listTools,buildWordIndex,loadWordIndex,format} from './chat-rat-query-20261017.mjs';

const line=r=>JSON.stringify(r);
const chat=(id,day,user,reply)=>[{type:'session_meta',payload:{id,timestamp:`2026-10-${day}T18:00:00Z`}},{type:'turn_context',payload:{model:'model-a'}},{type:'response_item',payload:{type:'message',role:'user',content:[{type:'input_text',text:user}]}},{type:'response_item',payload:{type:'message',role:'assistant',content:[{type:'output_text',text:reply}]}}].map(line).join('\n')+'\n';
async function library(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'chat-rat-query-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const cfg=settings(root,path.join(root,'library'));const dir=path.join(cfg.codex,'sessions');await fs.mkdir(dir,{recursive:true});
 await fs.writeFile(path.join(dir,'a.jsonl'),chat('portfolio','07','I want a portfolio website that opens plain and turns into Astra.','The portfolio site has three acts and Portfolio Puffer keeps it current.'));
 await fs.writeFile(path.join(dir,'b.jsonl'),chat('drums','08','Drum Dog should manage Ableton projects.','Drum Dog is registered but not built.'));
 await fs.writeFile(path.join(dir,'c.jsonl'),chat('pets','09','List the pets and their moods.','Nine moods per pet.'));
 await indexChats(cfg);return {cfg,dir};}

test('terms drop stop words and fold plurals',()=>{assert.deepEqual(terms('What are the pets doing with their portfolios?'),['pet','doing','portfolio']);assert.deepEqual(terms('class glass'),['class','glass']);});
test('ask ranks the right chat first and quotes it',async t=>{const {cfg}=await library(t);const a=await ask(cfg,'what was the portfolio website supposed to be');assert.equal(a.results[0].title.startsWith('I want a portfolio'),true);assert.ok(a.results[0].quotes.some(q=>/three acts/.test(q.text)));assert.match(format(a),/Tool: portfolio-website-supposed/);});
test('a new question invents a tool; a similar one reuses and grows it',async t=>{const {cfg}=await library(t);const first=await ask(cfg,'portfolio website plan');assert.equal(first.tool.reused,false);const second=await ask(cfg,'the portfolio website plan details',{also:['Puffer']});assert.equal(second.tool.reused,true);assert.equal(second.tool.name,first.tool.name);assert.ok(second.tool.terms.includes('puffer'));const tools=await listTools(cfg);assert.equal(tools.length,1);assert.equal(tools[0].uses,2);const other=await ask(cfg,'drum dog ableton');assert.equal(other.tool.reused,false);assert.equal((await listTools(cfg)).length,2);});
test('word index is cached until the archive is saved again, then rebuilds only changed chats',async t=>{const {cfg,dir}=await library(t);await buildWordIndex(cfg);let r=await loadWordIndex(cfg);assert.equal(r.cached,true);await fs.appendFile(path.join(dir,'c.jsonl'),line({type:'response_item',payload:{type:'message',role:'user',content:[{type:'input_text',text:'Add a zebra pet.'}]}})+'\n');await indexChats(cfg);r=await loadWordIndex(cfg);assert.equal(r.cached,false);assert.equal(r.rebuilt,1);assert.equal(r.kept,2);assert.ok(r.index.postings.zebra);});
test('pinned chats stay on top and date range filters',async t=>{const {cfg}=await library(t);const pets=(await ask(cfg,'pets moods')).results[0].id;const a=await ask(cfg,'portfolio pets',{pin:[pets]});assert.equal(a.results[0].id,pets);assert.equal(a.results[0].pinned,true);const b=await ask(cfg,'portfolio drum pets',{from:'20261008'});assert.ok(b.results.every(r=>r.date>='20261008'));});
test('tools and indexes stay in the library, outside the repo',async t=>{const {cfg}=await library(t);await ask(cfg,'portfolio');const files=await fs.readdir(cfg.library);assert.ok(files.includes('tools'));assert.ok(files.some(f=>f.startsWith('word-index-')));});
test('harness reminders and repeated messages are never quoted',async t=>{const {cfg,dir}=await library(t);const reply={type:'response_item',payload:{type:'message',role:'assistant',content:[{type:'output_text',text:'portfolio colors look good'}]}};await fs.writeFile(path.join(dir,'d.jsonl'),chat('noisy','10','<system-reminder>portfolio portfolio portfolio</system-reminder> the portfolio colors','portfolio colors look good')+line(reply)+'\n');await indexChats(cfg);const a=await ask(cfg,'portfolio colors');const q=a.results.find(r=>r.quotes.some(x=>/colors/.test(x.text))).quotes;assert.ok(q.every(x=>!/system-reminder/.test(x.text)));assert.equal(new Set(q.map(x=>x.text)).size,q.length);});
test('a question whose words are already inside a tool reuses it',async t=>{const {cfg}=await library(t);const big=await ask(cfg,'what was the portfolio website supposed to be',{also:['Puffer','autobiography']});const small=await ask(cfg,'portfolio website plan');assert.equal(small.tool.reused,true);assert.equal(small.tool.name,big.tool.name);});
